/**
 * Release signing material is resolved in this order:
 *   1. local-signing/keystore.properties (generated by tools/generate-release-key.sh, git-ignored)
 *   2. NOSCROLL_KEYSTORE_FILE / NOSCROLL_KEYSTORE_PASSWORD / NOSCROLL_KEY_ALIAS / NOSCROLL_KEY_PASSWORD
 *      environment variables (used by CI, sourced from GitHub Secrets)
 *   3. nothing -> the release build is left unsigned, rather than silently falling back to the
 *      debug key. `./gradlew :app:reportSigningSource` says which of the three is in effect.
 * Passwords are never printed by the build.
 */
data class SigningMaterial(
    val storeFile: File,
    val storePassword: String,
    val keyAlias: String,
    val keyPassword: String,
    val source: String,
)

fun resolveSigningMaterial(): SigningMaterial? {
    val propsFile = rootProject.file("local-signing/keystore.properties")
    if (propsFile.exists()) {
        val props = Properties().apply { FileInputStream(propsFile).use { load(it) } }
        val store = props.getProperty("storeFile")?.let { path ->
            File(path).takeIf { it.isAbsolute } ?: rootProject.file(path)
        }
        val storePassword = props.getProperty("storePassword")
        val alias = props.getProperty("keyAlias")
        val keyPassword = props.getProperty("keyPassword") ?: storePassword
        if (store != null && store.exists() && storePassword != null && alias != null && keyPassword != null) {
            return SigningMaterial(store, storePassword, alias, keyPassword, "local-signing/keystore.properties")
        }
    }
    val envStore = System.getenv("NOSCROLL_KEYSTORE_FILE")
    val envStorePassword = System.getenv("NOSCROLL_KEYSTORE_PASSWORD")
    val envAlias = System.getenv("NOSCROLL_KEY_ALIAS")
    val envKeyPassword = System.getenv("NOSCROLL_KEY_PASSWORD") ?: envStorePassword
    if (envStore != null && envStorePassword != null && envAlias != null && envKeyPassword != null) {
        val file = File(envStore).takeIf { it.isAbsolute } ?: rootProject.file(envStore)
        if (file.exists()) {
            return SigningMaterial(file, envStorePassword, envAlias, envKeyPassword, "environment variables")
        }
    }
    return null
}

val signingMaterial = resolveSigningMaterial()

