/**
 * Copies the signed release APK into dist/ alongside its SHA-256, which is what the README and
 * the GitHub release flow both point at.
 */
val distDir = rootProject.layout.projectDirectory.dir("dist")

tasks.register("packageDist") {
    group = "distribution"
    description = "Copies the release APK and its SHA-256 checksum into dist/."
    dependsOn("assembleRelease")

    val versionName = android.defaultConfig.versionName
    val apkDir = layout.buildDirectory.dir("outputs/apk/release")
    val outDir = distDir

    doLast {
        val source = apkDir.get().asFile.listFiles()?.firstOrNull { it.name.endsWith(".apk") }
            ?: throw GradleException("No release APK found in ${apkDir.get().asFile}")
        val target = outDir.asFile.also { it.mkdirs() }.resolve("NoScroll-v$versionName.apk")
        source.copyTo(target, overwrite = true)

        val digest = MessageDigest.getInstance("SHA-256")
        target.inputStream().use { input ->
            val buffer = ByteArray(64 * 1024)
            while (true) {
                val read = input.read(buffer)
                if (read <= 0) break
                digest.update(buffer, 0, read)
            }
        }
        val hex = digest.digest().joinToString("") { "%02x".format(it) }
        outDir.asFile.resolve("${target.name}.sha256").writeText("$hex  ${target.name}\n")
        logger.lifecycle("dist/${target.name}")
        logger.lifecycle("dist/${target.name}.sha256  ->  $hex")
    }
}

tasks.register("reportSigningSource") {
    group = "verification"
    description = "Reports which signing material the release build will use (never prints passwords)."
    val source = signingMaterial?.source
    val store = signingMaterial?.storeFile?.name
    val alias = signingMaterial?.keyAlias
    doLast {
        if (source == null) {
            logger.lifecycle("Release signing: NOT CONFIGURED (release builds will be unsigned)")
        } else {
            logger.lifecycle("Release signing: configured from $source (keystore=$store, alias=$alias)")
        }
    }
}
